param([Parameter(Mandatory)][int]$RootPid,[string]$PhaseFile,[string]$OutputPath=(Join-Path $PWD 'process-network-observation.jsonl'),[int]$SampleIntervalSeconds=1,[int]$GraceSeconds=3)
Set-StrictMode -Version Latest
$seen=@{};$samples=@();$endAt=$null
function Get-Phase { if($PhaseFile -and (Test-Path -LiteralPath $PhaseFile)){(Get-Content -Raw -LiteralPath $PhaseFile).Trim()}else{'FLOW_ACTIVE'} }
function Descendants([int]$targetPid){$all=Get-CimInstance Win32_Process;$ids=@($targetPid);$changed=$true;while($changed){$changed=$false;foreach($p in $all){if($ids -contains [int]$p.ParentProcessId -and $ids -notcontains [int]$p.ProcessId){$ids+=,[int]$p.ProcessId;$changed=$true}}};$ids}
do{$phase=Get-Phase;if($phase -eq 'FLOW_END' -and -not $endAt){$endAt=(Get-Date).ToUniversalTime().AddSeconds($GraceSeconds)};$ids=Descendants $RootPid;foreach($id in $ids){$seen[$id]=$true};foreach($id in $seen.Keys){$proc=Get-Process -Id $id -ErrorAction SilentlyContinue;$name=if($proc){$proc.ProcessName}else{'exited'};$tcp=@(Get-NetTCPConnection -OwningProcess $id -ErrorAction SilentlyContinue);if(!$tcp){$row=[ordered]@{timestampUtc=(Get-Date).ToUniversalTime().ToString('o');phase=$phase;kind='Sample';pid=$id;process=$name;rootPid=$RootPid;relation=if($id -eq $RootPid){'root'}else{'descendant'};localAddress=$null;localPort=$null;remoteAddress=$null;remotePort=$null;state=$null};$samples+=,$row;$row|ConvertTo-Json -Compress|Add-Content -LiteralPath $OutputPath}else{foreach($c in $tcp){$row=[ordered]@{timestampUtc=(Get-Date).ToUniversalTime().ToString('o');phase=$phase;kind='Tcp';pid=$id;process=$name;rootPid=$RootPid;relation=if($id -eq $RootPid){'root'}else{'descendant'};localAddress=$c.LocalAddress;localPort=$c.LocalPort;remoteAddress=$c.RemoteAddress;remotePort=$c.RemotePort;state=$c.State};$samples+=,$row;$row|ConvertTo-Json -Compress|Add-Content -LiteralPath $OutputPath}}};Start-Sleep -Seconds $SampleIntervalSeconds}while(!$endAt -or (Get-Date).ToUniversalTime() -lt $endAt)
$summary=[ordered]@{kind='Summary';sampleCount=$samples.Count;observedPids=@($seen.Keys);nonLoopback=@($samples|Where-Object{$_.remoteAddress -and $_.remoteAddress -notin @('127.0.0.1','::1')});expectedEndpoint='runtime-resolved configured OpenAI endpoint (api.openai.com); no fixed IP';unexpectedChildClassification='Node and conhost are recorded separately; reviewer classifies any other child'};$summary|ConvertTo-Json -Depth 6|Set-Content -LiteralPath ($OutputPath+'.summary.json')
